def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and (ny, nx) not in seen and grid[ny][nx] == color:
                        seen.add((ny, nx))
                        stack.append((ny, nx))
            if len(cells) < 8:
                continue
            y0 = min(y for y, x in cells); y1 = max(y for y, x in cells)
            x0 = min(x for y, x in cells); x1 = max(x for y, x in cells)
            if y1-y0 < 2 or x1-x0 < 2:
                continue
            perimeter = {(y, x) for y in range(y0, y1+1) for x in range(x0, x1+1)
                         if y in (y0, y1) or x in (x0, x1)}
            if len(cells) != len(perimeter) or not perimeter.issubset(set(cells)):
                continue
            # The interior parity selects the fill color.
            inner_h, inner_w = y1-y0-1, x1-x0-1
            fill = 2 if inner_h % 2 == 0 and inner_w % 2 == 0 else 7
            for y in range(y0+1, y1):
                for x in range(x0+1, x1):
                    out[y][x] = fill
    return out

